-- 아기상어 챌린지 (wb9xzdk9 / 아기상어-챌린지)
update public.memes set
  description = '''아기상어 챌린지''는 더핑크퐁컴퍼니의 어린이 노래 ''아기상어''에 맞춰 짧은 춤 영상을 찍어 SNS에 올리고 다른 사람을 태그하는 놀이형 유행을 가리킨다. 노래는 2015년 핑크퐁 영상으로 처음 공개됐고, 2016년에는 춤 동작을 더한 ''핑크퐁 아기상어 체조'' 영상이 나왔다. 이후 2018년 8월 무렵부터 서구권에서 ''#BabySharkChallenge'' 해시태그와 함께 여러 사람이 자신만의 춤 영상을 올리는 방식으로 퍼졌다. 아이를 위한 동요가 전 세계 어른들의 참여형 유행으로 번진 대표 사례로 소개되며, 특히 어린이 콘텐츠가 어른들의 놀이로 옮겨 간 흐름을 설명할 때 자주 인용된다.',
  origin = '원본 영상은 2015년 더핑크퐁컴퍼니가 공개했다. 위키백과 영문판은 2015년 11월 말 업로드를 기록하고, 가장 많이 알려진 ''아기상어 댄스'' 영상은 2016년 6월 17일 업로드된 것으로 적는다. 2017년 인도네시아 등 아시아에서 먼저 화제가 됐고, 2018년 8월부터 서구권에서 챌린지 열풍이 불었다. 챌린지의 정확한 시작일은 출처마다 달라 확정하지 않았다.',
  usage_note = '어린이 노래가 어른들의 참여형 챌린지로 번진 사례를 설명할 때 쓴다. 해외에서 한국 어린이 콘텐츠가 유행한 흐름을 소개하는 맥락에서 인용하기 좋다.',
  caution = '챌린지의 국내 유행 규모와 구체적인 시작일은 확인된 자료가 적으므로 단정하지 않는다. 2018년 확산을 말할 때는 서구권 중심 사례였음을 함께 밝히는 것이 안전하다.',
  usage_examples = '[{"situation":"어린이 콘텐츠가 어른들의 유행으로 번진 사례를 설명할 때","text":"동요 하나가 SNS 챌린지로 번지는 현상은 2018년 아기상어 챌린지에서 잘 드러났다."},{"situation":"짧은 춤 영상의 확산 힘을 이야기할 때","text":"아기상어 챌린지처럼 누구나 따라 할 수 있는 단순한 춤이 가장 빨리 퍼진다."}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'wb9xzdk9'
  and slug = '아기상어-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

