-- Hype Boy 챌린지 (3ke2xcrg / Hype-Boy-챌린지)
update public.memes set
  description = '''Hype Boy''는 뉴진스의 EP ''New Jeans''에 실린 두 번째 싱글이다. 뮤직비디오는 2022년 7월 23일에 먼저 공개됐고, 음원은 8월 1일에 정식 발매됐다. 독특하고 중독성 있는 안무와 후렴구가 주목받으며 틱톡 등에서 이 곡에 맞춘 댄스 챌린지가 번졌다. 국내 음원 차트에서 2위까지 올랐고, 글로벌 빌보드 차트에도 진입했다. 다만 일부 댄서가 올린 챌린지 영상이 안무를 희화화했다는 논란이 일면서, 챌린지 문화의 장단점을 함께 보여주는 사례로 언급되기도 한다.',
  origin = '소속사 ADOR가 2022년 7월 23일 뮤직비디오를 네 가지 버전으로 공개했고, 8월 1일 두 번째 싱글로 음원이 발매됐다. 위키백과 영문판은 이 곡을 데뷔 앨범의 두 번째 싱글로 기록한다. 2022년 8월 24일 댄서 두 명이 올린 챌린지 영상은 안무를 희화화했다는 비판을 받아 삭제됐고, 8월 26일 사과가 이어졌다. 서울신문은 8월 27일 이 논란을 보도했다.',
  usage_note = '2022년 뉴진스 곡을 중심으로 한 댄스 챌린지 흐름을 설명할 때 쓴다. 챌린지가 SNS에서 얼마나 빠르게 퍼지는지 예시로 들기 좋다.',
  caution = '챌린지 영상 중에는 안무를 조롱하듯 편집한 사례가 있어 논란이 됐다. 이 밈을 소개할 때는 원곡과 팬, 안무가에 대한 존중을 전제로 하고, 특정 댄서나 크루를 비난하는 문맥으로 쓰지 않는다.',
  usage_examples = '[{"situation":"여름 댄스 챌린지 트렌드를 정리할 때","text":"2022년 ''Hype Boy'' 챌린지처럼 안무 하나가 한 시즌의 SNS 유행을 이끌기도 한다."},{"situation":"챌린지 영상을 기획할 때","text":"원곡 안무를 존중하는 편집이 논란을 줄이는 가장 쉬운 방법이다."}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '3ke2xcrg'
  and slug = 'Hype-Boy-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

