-- 얼음(제프프) (5tzq929b / 얼음(제프프))
update public.memes set
  description = '''오징어 게임'' 시즌2에서 성기훈이 ''무궁화 꽃이 피었습니다'' 게임 중 참가자들에게 ''얼음!''을 외치는 장면을 유튜버 제프프가 뮤지컬 넘버처럼 편곡한 2차 창작 영상이다. 원작의 긴박한 장면과 대비되는 희망찬 멜로디가 웃음 포인트가 되면서 밈으로 퍼졌다. 영상은 ''성기훈-얼음''이라는 제목으로 올라왔고 길이는 약 1분 24초다. 넷플릭스가 극 중 대사를 활용한 댓글을 남겼다는 소식도 전해졌다. 진지한 상황을 유쾌하게 뒤집는 리믹스 밈을 가리킬 때 쓰인다.',
  origin = '제프프가 만든 ''성기훈-얼음'' 영상은 2025년 1월 무렵 공개돼 시즌2 밈으로 퍼졌다. 위픽레터는 2025년 1월 17일 기사에서 공개 5일 만에 조회수 160만 회를 넘었다고 전했다. 팬마음 커뮤니티 글은 1월 21일 게시물에서 영상 제목과 길이를 소개했다. 원곡이나 공식 음원 여부는 열어본 출처에서 확인되지 않았다.',
  usage_note = '진지한 장면을 유쾌하게 뒤집는 리믹스 밈을 설명할 때 쓴다. 원작 장면과 편곡의 대비가 핵심인 2차 창작물을 소개하는 글에 적합하다.',
  caution = '이 곡은 공식 음원이라는 근거가 확인되지 않았으므로 2차 창작물로 소개한다. 조회수 수치는 한 출처에서만 확인되어 인용할 때 시점과 출처를 함께 밝혀야 한다.',
  usage_examples = '[{"situation":"시즌2 밈을 정리하는 글에서","text":"시즌2 밈 중에는 ''얼음!'' 장면을 뮤지컬풍으로 편곡한 리믹스도 있었다."},{"situation":"진지한 상황을 유머로 바꾸는 예시를 들 때","text":"회의실의 긴장을 ''얼음!'' 뮤지컬 리믹스처럼 한 줄 농담으로 풀었다."}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '5tzq929b'
  and slug = '얼음(제프프)'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

