-- 런던의 1초 (k2e4g7ur / 런던의-1초)
update public.memes set
  description = '2012년 런던올림픽 여자 펜싱 에페 개인전 준결승에서 신아람이 독일의 브리타 하이데만에게 패한 판정 논란을 가리킨다. 연장전에서 신아람이 세 차례 공격을 막는 동안 시계가 흐르지 않았고, 네 번째 공격을 허용해 결승 진출권을 놓쳤다. 비디오 판독에서 1초가 넘는 시간이 지났음이 확인됐지만 판정은 바뀌지 않았다. 국제펜싱연맹은 오심을 인정하면서도 번복하지 않았고, 이 사건은 올림픽 5대 판정 논란 중 하나로 꼽혔다. ''런던의 1초''라는 표현은 이 사건을 가리키는 말로 쓰인다.',
  origin = '2012년 7월 30일 런던 현지 기준 엑셀 경기장 남측 아레나에서 열린 준결승으로, 한국시간으로는 7월 31일이다. 세계일보는 국제펜싱연맹 심판진이 약 30분 회의 끝에 하이데만의 승리를 결정했다고 보도했다. 이투데이는 8월 1일 이 장면을 ''신아람 눈물의 1초''라는 제목으로 올림픽 5대 판정 논란에 포함해 다뤘다.',
  usage_note = '억울하게 불리한 판정을 받은 상황을 비유할 때 쓴다. 스포츠 판정 논란을 다룬 글에서 대표 사례로 인용하기 좋다.',
  caution = '점수 등 세부 경기 기록은 열어본 출처마다 보도 범위가 달라 인용하지 않는다. 특정 선수를 조롱하거나 비하하는 문맥으로 쓰지 않도록 주의한다.',
  usage_examples = '[{"situation":"스포츠 판정 논란을 비유할 때","text":"그 골이 취소되면서 우리는 또 한 번 런던의 1초를 겪었다."},{"situation":"억울한 처리 결과를 이야기할 때","text":"1초 차이로 밀려난 신청이라니, 말 그대로 런던의 1초 같은 결과다."}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'k2e4g7ur'
  and slug = '런던의-1초'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

