-- 뉴진스 Super Shy 챌린지 (7xrfcr9u / 뉴진스-Super-Shy-챌린지)
update public.memes set
  description = '''Super Shy''는 뉴진스가 2023년 7월 7일 공개한 곡이다. 유튜브가 이 곡을 알리기 위해 쇼츠에서 연 공식 댄스 챌린지가 ''#ImSuperShy'' 챌린지다. 참여자는 공식 안무에 자신만의 동작을 더해 쇼츠 영상을 올리는 방식이었다. 뉴진스 멤버 민지, 하니, 다니엘, 해린, 혜인이 먼저 챌린지 영상을 올렸고, 전 세계 팬이 참여할 수 있도록 열렸다. 음원과 뮤직비디오 공개에 맞춰 시작된 캠페인이라 음악 홍보와 플랫폼 캠페인이 결합된 사례로 볼 수 있다.',
  origin = '2023년 7월 7일 유튜브 공식 블로그를 통해 챌린지가 발표됐고, 같은 날 ''Super Shy'' 음원과 뮤직비디오가 공개됐다. 위키백과 영문판도 같은 날 디지털 발매를 기록하며 유튜브 쇼츠 댄스 챌린지를 함께 소개한다. 이 캠페인은 2024년 클리오 뮤직 어워즈에서 은상을 받은 것으로도 알려져 있다.',
  usage_note = '2023년 쇼츠 기반 댄스 챌린지의 공식 사례를 설명할 때 쓴다. 음원 홍보가 플랫폼 챌린지로 확장된 흐름을 소개할 때 인용하기 좋다.',
  caution = '챌린지 영상은 누구나 참여할 수 있었지만 개별 영상의 조회수나 참여 규모는 확인된 출처에 없다. 공식 캠페인 정보와 사용자 영상 내용을 구분해서 쓰는 것이 필요하다.',
  usage_examples = '[{"situation":"짧은 영상 플랫폼 캠페인을 소개할 때","text":"유튜브는 뉴진스의 ''Super Shy'' 발매에 맞춰 쇼츠 댄스 챌린지를 공식으로 열었다."},{"situation":"팬 콘텐츠 제작을 권할 때","text":"공식 안무에 내 동작을 얹어 #ImSuperShy 쇼츠를 올려 보자."}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '7xrfcr9u'
  and slug = '뉴진스-Super-Shy-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

