-- AOA 심쿵해 하트춤 (xbkj59c9 / AOA 심쿵해 하트춤)
update public.memes set
  description = 'AOA가 2015년 6월 22일 발매한 EP 《Heart Attack》의 타이틀곡 ''심쿵해''에서 선보인 포인트 안무를 가리키는 말이다. 소속사 FNC엔터테인먼트는 공개 직후 세 가지 포인트 동작을 따로 소개했다. ''심장어택춤''은 매력적인 상대를 만났을 때 심장이 내려앉는 느낌을, ''반해버렷춤''은 애교 있는 표정으로 상대의 관심을 끄는 동작을 표현한다. ''이리커몬춤''은 상대를 손짓으로 부르는 동작이다. 세 동작 모두 건강하고 섹시하며 발랄한 매력을 보여주려는 취지로 짜였다.',
  origin = '2015년 6월 22일 FNC엔터테인먼트에서 발매된 EP 《Heart Attack》의 타이틀곡 ''심쿵해''가 출처다. 세 가지 포인트 안무 영상은 2015년 6월 29일 그룹의 공식 페이스북에 공개됐다.',
  usage_note = '2015년 걸그룹 포인트 안무를 회고하거나 AOA의 대표 동작을 소개할 때 ''심장어택춤''처럼 동작 이름을 붙여 쓴다. 심쿵 콘셉트나 하트 포즈 이야기에 가볍게 인용하기 좋다.',
  caution = '동작 이름은 기사에 실린 명칭을 기준으로 쓰고, 손 모양이나 순서 같은 세부 동작은 원본 영상을 확인하기 전까지 단정하지 않는다. 팬 커버 유행의 규모는 확인된 자료가 없으니 과장하지 않는다.',
  usage_examples = '[{"situation":"2015년 여름 노래 얘기하는 대화","text":"그때 심쿵해 심장어택춤 다 따라 췄잖아"},{"situation":"걸그룹 하트 안무 추천 글 댓글","text":"심쿵해 반해버렷춤부터 보고 와, 진짜 귀엽다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'xbkj59c9'
  and slug = 'AOA 심쿵해 하트춤'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

