-- 내일봬요누나 (w3tdzhmt / 내일봬요누나)
update public.memes set
  description = '''내일 봬요, 누나''는 티빙 오리지널 ''환승연애2''에서 출연자 정현규가 연상의 성해은을 첫 데이트 상대로 고르며 한 말이다. 망설임 없이 호감을 드러낸 직진 표현으로 받아들여져 방송 이후 화제가 됐다. 성해은은 2023년 1월 유튜브 채널 ''뱀집''에 출연해 그 말을 들었을 때 놀랐고 반응이 컸다고 회상했다. 2022년 9월 방송 소개 기사에서는 정현규가 새 입주자로 등장해 이 장면에서 성해은의 이름을 부른 것으로 소개됐다. 지금은 솔직하게 마음을 표현하는 장면을 가볍게 흉내 내거나, 직진 고백을 유쾌하게 묘사할 때 쓰는 말이다.',
  origin = '2022년 방송된 티빙 오리지널 ''환승연애2''에서 출연자 정현규가 성해은에게 한 말이다. 방송 회차는 확인되지 않았으며, 성해은은 2023년 1월 유튜브 인터뷰에서 그 말을 들었을 때의 반응을 회상했다.',
  usage_note = '솔직하고 당당하게 호감을 드러내는 장면을 가볍게 흉내 낼 때, 또는 직진 고백을 유쾌하게 묘사할 때 쓴다.',
  caution = '실제 방송 속 상황과 출연자의 말을 바탕으로 한 말이므로, 당사자가 아닌 사람을 놀리는 데 쓰면 사생활 이야기로 오해받을 수 있다. 관계에 대한 이야기는 기사에 실린 내용만 근거로 삼는다.',
  usage_examples = '[{"situation":"카톡","text":"내일 봬요 누나ㅋㅋ 오늘 바로 약속 잡자"},{"situation":"SNS 댓글","text":"이 장면 아직도 기억나, 내일 봬요 누나 명대사"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'w3tdzhmt'
  and slug = '내일봬요누나'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

