-- 파리의 연인 - 이 안에 너 있다 (gbhs35gh / 파리의-연인---이-안에-너-있다)
update public.memes set
  description = '''이 안에 너 있다''는 2004년 드라마 ''파리의 연인''에서 이동건이 연기한 윤수혁이 한 고백 대사다. 방송 당시 시청자들에게 강한 반응을 얻었고, 2004년 연말 유행어 집계에서도 같은 드라마의 ''애기야 가자''와 함께 드라마 부문에 올랐다. 고백 장면을 과장되게 흉내 낼 때 쓰이며, 2024년 기사에서도 드라마 명대사로 다뤄졌고, 같은 드라마에서 박신양이 연기한 인물의 패션과 대사도 함께 유행을 일으켰다고 소개됐다. 지금은 2000년대 드라마 유행어를 회상하는 자리에서 가볍게 인용되는 말이다.',
  origin = '2004년 드라마 ''파리의 연인''의 대사다. 2004년 12월 서울신문 기사는 인터넷 팬 투표에서 같은 드라마의 ''애기야 가자''가 올해 최고 유행어로 꼽혔다고 전하며, 이 대사는 순위 없이 함께 언급된다. 이 대사가 1위였다는 근거는 확인되지 않았다.',
  usage_note = '진지하지 않은 고백 장면을 장난스럽게 흉내 낼 때, 혹은 2000년대 드라마 유행어를 회상할 때 쓴다.',
  caution = '드라마 속 과장된 고백 대사라 진지한 고백에 그대로 쓰면 어색하게 웃음거리가 될 수 있다. 장난으로 흉내 낼 때도 상대가 함께 웃을 수 있는 자리에서 쓰는 것이 안전하다.',
  usage_examples = '[{"situation":"카톡","text":"이 안에 너 있다ㅋㅋ (고백 흉내 내는 중)"},{"situation":"SNS 댓글","text":"2004년 드라마 명대사 다시 보니 반갑다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'gbhs35gh'
  and slug = '파리의-연인---이-안에-너-있다'
