-- 05학번이즈백 (39frzfq4 / 05학번이즈백)
update public.memes set
  description = '''05학번 이즈 백''은 유튜브 채널 피식대학의 콩트 시리즈로, 2000년대 대학 생활의 패션과 유행을 그대로 재현한 콘텐츠를 가리킨다. 피식대학이 대학생 공감 코미디를 하다 이용주의 제안으로 05학번의 추억을 소재로 만든 오리지널 콘텐츠다. 2021년 3월 무렵에는 이미 채널의 대표 코너로 꼽혔고, 김민수는 이를 ''하이퍼 리얼리즘 코미디''라고 불렀다. 시리즈에는 한사랑산악회처럼 함께 인기를 끈 코너가 있고, 이후 05학번이즈히어와 피식쇼 같은 파생 프로그램도 나왔다. 밈으로는 옛 학번의 추억이나 ''나 때는'' 식 허세를 놀릴 때 쓰인다.',
  origin = '2021년 3월 바이라인네트워크 인터뷰에 따르면 피식대학은 대학생 공감 콘텐츠 이후 이용주의 제안으로 05학번 추억을 소재로 한 오리지널 콘텐츠를 만들었다. 2023년 5월 오센 기사는 이 콘텐츠가 2000년대 패션을 입고 ''UCC''라는 이름으로 찍는 콘텐츠라고 설명한다.',
  usage_note = '옛 학번의 추억이나 ''나 때는'' 식 허세를 놀리거나, 2000년대 복고 콘셉트를 가볍게 언급할 때 쓴다.',
  caution = '실제 학번이나 특정 개인을 깎아내리는 말로 쓰면 농담이 아닌 비하로 받아들여질 수 있다. 과장된 콩트이므로 실제 그 시절 경험을 단정하는 근거로 인용하지 않는 것이 좋다.',
  usage_examples = '[{"situation":"카톡","text":"그 옷 완전 05학번이즈백이네ㅋㅋ"},{"situation":"SNS 댓글","text":"우리 때 얘기하면 05학번이즈백 찍자는 말 나올 듯"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '39frzfq4'
  and slug = '05학번이즈백'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

