-- 박상영 할 수 있다 (bjj96x3t / 박상영-할-수-있다)
update public.memes set
  description = '2016 리우올림픽 펜싱 남자 에페 개인전 결승에서 박상영 선수가 경기 중 스스로에게 되뇐 말이다. 10-14로 뒤져 패색이 짙던 상황에서 ''할 수 있다''를 되뇌었고, 이후 5연속 득점으로 15-14 역전 금메달을 땄다. 세계랭킹 21위였던 선수가 3위 상대를 꺾은 역전극이라 이 장면은 크게 화제가 됐다. 쉬는 시간에 눈을 감고 같은 말을 반복하는 모습은 중계 화면에 잡혔다고 전해진다. 지금은 힘든 상황에서 자신을 다독이며 버티자는 뜻으로 쓰는 말이다.',
  origin = '2016년 8월 9일(현지 시간) 브라질 리우데자네이루 올림픽 펜싱 남자 에페 개인전 결승이다. 서울신문과 위키트리 기사, 위키백과에 따르면 상대는 헝가리의 임레 게저(세계랭킹 3위)였고 박상영은 세계랭킹 21위였다.',
  usage_note = '위기 상황에서 스스로를 다독이며 버티는 장면을 이야기할 때 쓰거나, 역경을 뒤집은 역전극을 칭찬할 때 인용한다.',
  caution = '2016년 실제 경기 맥락을 담은 말이므로 가벼운 상황에 과하게 쓰면 농담이 될 수 있다. 발언의 정확한 표현은 ''그래 할 수 있다''와 ''나는 할 수 있다''처럼 기사마다 달라, 그대로 인용할 때는 원 기사를 확인하는 편이 안전하다.',
  usage_examples = '[{"situation":"카톡","text":"시험 망했는데 그래 할 수 있다, 할 수 있다..."},{"situation":"SNS 댓글","text":"10-14에서 15-14 뒤집은 박상영처럼 끝까지 가보자"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'bjj96x3t'
  and slug = '박상영-할-수-있다'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

