-- 딱지녀 밈 (cpxnd4p6 / 딱지녀-밈)
update public.memes set
  description = '''딱지녀 밈''은 넷플릭스 ''오징어 게임'' 시즌3 마지막 장면에 깜짝 등장한 케이트 블란쳇을 가리키는 별칭이다. 넷플릭스 튜더는 그를 미국 쪽 모집책(American Recruiter)으로 소개했고, 연출을 맡은 황동혁 감독은 한국 쪽 모집책을 맡은 공유(Gong Yoo)와 짝을 이루는 인물이라고 설명했다. 엔딩에서 프론트맨이 LA 도심 신호 대기 중 차창 너머로, 정장 차림의 그가 골목에서 절박해 보이는 남성과 딱지치기를 하는 모습을 본다. 시즌1 딱지남 장면을 떠올리게 하는 정장 차림과 딱지치기 구도가 특징이다.',
  origin = '2025년 6월 말 공개된 ''오징어 게임'' 시즌3 마지막 화의 엔딩 장면이다. 넷플릭스 튜더는 6월 30일 기사에서 케이트 블란쳇이 맡은 역할을 미국 쪽 모집책으로 소개했고, 오센은 7월 1일 특별출연 스틸을 공개하며 정장 차림의 딱지치기 장면을 전했다. 열람한 두 기사 모두 그의 고유 캐릭터 이름은 언급하지 않았다.',
  usage_note = '시즌3 엔딩의 깜짝 출연을 언급하거나, 예상 밖의 인물이 뜻밖의 자리에 나타난 상황을 농담으로 말할 때 쓴다.',
  caution = '시즌3 결말 장면을 다루므로 아직 보지 않은 사람에게는 스포일러가 된다. 블란쳇의 역할 설명은 기사마다 다르므로 ''미국 쪽 모집책'' 같은 표현을 단정적으로 옮기기보다 출처를 함께 밝히는 편이 안전하다.',
  usage_examples = '[{"situation":"카톡","text":"시즌3 엔딩에 그 배우 나온 거 실화냐, 딱지녀 등장은 진짜 반전이었다"},{"situation":"SNS 댓글","text":"정장 입고 골목에서 딱지치기하는 장면 다시 보니까 아직도 실감 안 난다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'cpxnd4p6'
  and slug = '딱지녀-밈'
