-- 스웨디시젤리 (dcq579zq / 스웨디시젤리)
update public.memes set
  description = '스웨디시젤리는 스웨덴산 구미 젤리, 특히 ''BUBS'' 제품처럼 쫀득하고 색이 화려한 젤리를 가리키는 말이다. 2024년 무렵 해외 틱톡에서 뉴욕의 북유럽 캔디 가게 영상이 화제가 되며 알려졌고, 국내에서는 두바이 초콜릿 다음 디저트 유행으로 번졌다. 정식 제품은 500g 한 봉지가 5만 원을 넘고 해외 직구 배송이 길어 구하기 어려운 편이다. 그래서 집에서 젤라틴이나 마시멜로로 만드는 비슷한 맛 레시피나 국산 대체품을 소개하는 콘텐츠가 많이 나온다.',
  origin = '국내 유행은 2024년 가을에 본격화됐다. 경향신문은 2024년 10월 19일 기사에서 해외 틱톡 영상이 먼저 퍼진 뒤 국내에서는 크리에이터 채널로 입소문이 났고, GS25가 그달 한정 판매를 밝혔다고 전했다. 아시아경제는 2024년 9월 22일 기사에서 유행의 정확한 시작 시점은 밝히지 않았으며, 정식 제품은 국내에 공식 판매되지 않아 해외 직구로 구하는 경우가 많다고 전했다.',
  usage_note = '해외 디저트 유행이나 편의점 신상 젤리 이야기를 할 때 쓰는 말이다. 쫀득한 식감의 수입 구미 젤리를 가리킨다는 뜻으로 쓰면 무난하다.',
  caution = '정품은 가격이 비싸고 배송 기간이 길어, 가격과 배송을 확인하지 않고 구매하면 실망하기 쉽다. 편의점 제품이나 집에서 만든 대체품을 정품과 같은 맛이라고 단정하지 않는 것이 좋다.',
  usage_examples = '[{"situation":"카톡","text":"요즘 스웨디시젤리 직구 가격 보고 놀랐어, 500g에 5만 원 넘더라"},{"situation":"SNS 댓글","text":"편의점에 스웨디시젤리 나오면 한번 먹어보고 싶다, 쫀득하다던데"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'dcq579zq'
  and slug = '스웨디시젤리'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

