-- 워크맨 선넘규 (4adudx69 / 워크맨-선넘규)
update public.memes set
  description = '''워크맨''은 JTBC 디지털 스튜디오 ''스튜디오 룰루랄라''가 만든 웹예능으로, 2019년 5월 처음 공개됐다. 다양한 직업과 아르바이트를 직접 체험하는 콘셉트에 진행자 장성규의 거침없는 입담이 더해지며 큰 인기를 얻었다. 같은 해 여름 단독 채널로 독립했고, 유튜브 리와인드 2019에서는 ''Top Breakout Creators'' 2위에 올랐다. ''선넘규''는 장성규의 선을 넘는 듯한 드립 스타일을 가리키는 말이다. 기사에서는 장성규가 장난스럽고 과감한 스타일로 선을 자주 넘는다고 소개된다.',
  origin = '2019년 5월 처음 공개된 웹예능으로, 더팩트(2019년 12월 3일)는 와썹맨의 성공 뒤에 기획된 프로그램이라고 전했다. 단독 채널 독립 시점은 더팩트가 2019년 7월, YTN이 8월로 달리 전해, 여기서는 같은 해 여름으로만 적는다. 장성규가 진행을 맡았다는 점은 뉴시스(2021년 9월 20일) 기사에서 확인된다.',
  usage_note = '재치 있게 선을 살짝 넘는 드립이나 과감한 입담을 칭찬할 때 쓴다. 장성규 특유의 거침없는 진행 스타일을 가리킬 때도 쓸 수 있다.',
  caution = '''선넘규''라는 별칭의 유래는 열람한 기사에서 확인하지 못했으므로 공식 용어처럼 단정하지 않는 것이 좋다. 선을 넘는 발언은 듣는 사람에 따라 불쾌감을 줄 수 있으니 실제 인물의 발언을 평가할 때는 맥락을 함께 말하는 편이 안전하다.',
  usage_examples = '[{"situation":"카톡","text":"방금 그 농담 워크맨 선넘규급이네 ㅋㅋ 웃다 쓰러짐"},{"situation":"SNS 댓글","text":"장성규 특유의 선 넘는 입담, 워크맨 초창기가 제일 웃겼다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '4adudx69'
  and slug = '워크맨-선넘규'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

