-- 몬주익의 영웅 (6bgyw6gb / 몬주익의-영웅)
update public.memes set
  description = '''몬주익의 영웅''은 1992년 바르셀로나 올림픽 남자 마라톤에서 금메달을 딴 황영조를 가리키는 별칭이다. 황영조는 레이스 막판 몬주익 언덕 비탈길에서 일본의 모리시타를 따돌리고 앞으로 치고 나가 2시간 13분 23초로 결승선을 끊었다. 결승선에 들어온 뒤 쓰러져 우는 모습까지 보도되며 큰 감동을 줬다. 당시 22세였던 황영조는 이 우승으로 크게 주목받았다. 당시 서울신문은 이 레이스를 ''몬주익 신화''라는 제목으로 전했고, 지금도 막판 극적 역전이나 끝까지 버틴 투혼을 말할 때 인용된다.',
  origin = '1992년 8월 바르셀로나 올림픽 남자 마라톤 결승이다. 서울신문(1992년 8월 11일)은 마지막 2km 몬주익 비탈길에서 모리시타가 바짝 따라붙어 지친 기색을 보이자 황영조가 앞으로 치고 나갔다고 전했다. 올림픽 마라톤 코스는 몬주익 언덕을 오르는 구간을 포함했다(Olympedia). ''몬주익의 영웅''이라는 별칭이 언제 처음 쓰였는지는 확인하지 못했다.',
  usage_note = '막판 대역전이나 끝까지 버틴 투혼을 칭찬할 때 쓴다. 극적인 역전 상황을 스포츠 중계처럼 과장해 말할 때 어울린다.',
  caution = '1992년 올림픽 상황을 가리키는 말이라 최근 경기에 그대로 붙이면 맥락이 어긋날 수 있다. 1992년 서울신문 기사에도 황영조의 이전 대회 기록이 서로 다르게 적혀 있어, 세부 기록을 인용할 때는 올림픽 공식 기록을 따로 확인해야 한다.',
  usage_examples = '[{"situation":"카톡","text":"막판 2km에서 뒤집다니, 이거 몬주익의 영웅급 역전이다"},{"situation":"SNS 댓글","text":"끝까지 버틴 투혼 보니 몬주익 언덕의 황영조 장면이 떠오른다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '6bgyw6gb'
  and slug = '몬주익의-영웅'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

