-- 중꺾마 (rk3w632x / 중꺾마)
update public.memes set
  description = '''중요한 것은 꺾이지 않는 마음''을 줄인 말로, 힘든 상황에서도 포기하지 않겠다는 태도를 응원할 때 쓴다. 2022년 리그 오브 레전드 월드 챔피언십에서 DRX가 우승하는 과정에서 선수 데프트(김혁규)가 한 말이 출처다. 그는 상대를 더 분석하기보다 자기 플레이를 잘하고 팀끼리 무너지지 않으면 충분히 이길 수 있다고 말했다. 기자가 이 말을 ''꺾이지 않는 마음''이라는 제목으로 옮기면서 널리 알려졌고, 이후 2022년 카타르 월드컵 16강 진출 과정에서 선수들이 이 문구를 적은 태극기를 들어 화제가 됐다. 과정을 중시하는 응원 문구로 MZ세대 사이에서 쓰인다.',
  origin = '2022 리그 오브 레전드 월드 챔피언십 조별리그 첫 패배 뒤 DRX 데프트가 한 인터뷰에서 출발했다. 그는 팀끼리 무너지지 않으면 충분히 이길 수 있다고 말했고, 기자가 이를 ''꺾이지 않는 마음''이라는 제목으로 옮겼다. 이 팀은 이후 롤드컵에서 우승했다. 같은 문구는 2022년 12월 카타르 월드컵 16강 진출 과정에서 태극기에 적혀 응원 구호처럼 퍼졌다.',
  usage_note = '힘든 상황에서도 끝까지 해 보자고 응원할 때 쓴다. 결과보다 과정을 중시하는 말이라 시험, 대회, 프로젝트처럼 버티는 상황에 잘 맞는다.',
  caution = '개인의 노력만 강조하는 말로 읽히면 구조적인 문제를 가리는 듯한 반응을 부를 수 있다는 비판도 있었다. 심각한 어려움을 겪는 사람에게 훈계처럼 건네지 않도록 상황을 가려 쓰는 것이 좋다.',
  usage_examples = '[{"situation":"시험 준비로 지친 친구에게 보내는 메시지","text":"점수 조금 아쉬워도 괜찮아, 중꺾마로 끝까지 가보자"},{"situation":"응원하는 팀이 지고 있는 경기 채팅방","text":"아직 경기 안 끝났어, 중꺾마!"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'rk3w632x'
  and slug = '중꺾마'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

