-- 그리마스 쉐이크(Grimace Shake) (d76hm4tg / 그리마스-쉐이크(Grimace-Shake))
update public.memes set
  description = '맥도날드가 캐릭터 그리마스의 생일을 기념해 2023년 6월 미국 매장에서 내놓은 보라색 셰이크를 마신 뒤 벌어진 틱톡 챌린지다. 참여자들은 셰이크를 한 모금 마시고 쓰러지거나 기이한 일을 겪은 것처럼 연출했고, 영상이 점점 범죄 현장이나 공포극처럼 바뀌면서 그리마스가 범인인 듯한 장면이 이어졌다. 실제 음료는 마셔도 안전하다고 보도됐다. 평범한 제품을 과장되게 저주받은 것처럼 꾸미는 농담으로 쓰이며, 해시태그 #GrimaceShake는 하루이틀 만에 조회수 5억 회를 넘겼다고 전해진다.',
  origin = '2023년 6월 미국 맥도날드가 그리마스의 52번째 생일을 기념해 한정 판매한 보라색 셰이크가 계기였다. 위키백과는 같은 시기 버거킹 와퍼 프로모션을 소재로 한 비슷한 유행이 영향을 줬다는 견해를 소개하며, 시초는 틱톡 사용자 한 명이 올린 영상으로 본다. 이후 틱톡에서 빠르게 확산됐다.',
  usage_note = '평범한 음식이나 일상의 사소한 물건을 과장되게 저주받은 것처럼 묘사할 때 쓴다. 실제로 해롭지 않은 장난이라는 점을 알고 쓰면 과하지 않다.',
  caution = '틱톡 영상 중에는 쓰러지거나 공포 장면으로 이어지는 연출이 많아 실제 건강 문제를 흉내 낸 것으로 받아들여질 수 있다. 음식 관련 장난을 식품 비하처럼 들리게 쓰지 않도록 주의하고, 어린이가 보는 자리에서는 가볍게 쓰는 것이 좋다.',
  usage_examples = '[{"situation":"신상 음료를 한 모금 마시고 과장할 때","text":"이 음료 한 모금에 바로 쓰러짐, 그리마스 쉐이크 찍는 중"},{"situation":"단체 채팅방에서 점심 사진을 공유할 때","text":"점심 메뉴 먹고 다들 그리마스 쉐이크 챌린지 찍는 줄 알았네"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'd76hm4tg'
  and slug = '그리마스-쉐이크(Grimace-Shake)'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

