-- 나를 돌아봐 (cdrxb4xa / 나를-돌아봐)
update public.memes set
  description = '1993년 4월 발매된 듀스의 1집 앨범 ''DEUX''에 실린 곡이며, 듀스의 대표곡으로 소개된다. 듀스는 힙합과 뉴잭스윙 계열 그룹으로 1993년 데뷔해 방송 활동을 시작했다. 2017년 영재와 천둥이 부른 커버가 듀스 버전의 리메이크로 소개되는 등 다른 가수들도 이 곡을 다시 불렀다. 같은 이름의 KBS 예능 프로그램에서는 이 곡이 여는 곡과 닫는 곡으로 쓰였다. 밈이나 대화에서는 주로 90년대 초 세련된 댄스음악의 분위기를 가리키는 말로 인용된다.',
  origin = '1993년 4월 발매된 듀스 1집 ''DEUX''의 두 번째 수록곡이다. 위키백과는 듀스가 1993년부터 방송 활동을 했다고 전하며, 이 곡을 앨범의 대표곡으로 소개한다. 곡의 작사·작곡·편곡 기록은 출처에서 개별 곡 기준으로 확인되지 않는다.',
  usage_note = '90년대 초 세련된 댄스음악의 분위기를 이야기할 때 인용하기 좋다. 곡을 직접 들어 본 감상과 함께 써야 과장되지 않는다.',
  caution = '작곡·편곡자 등 세부 크레딧을 출처 없이 단정해 쓰면 틀릴 수 있다. 발매일도 출처마다 4월 1일과 4월 23일로 달라 날짜를 인용하지 않는 것이 안전하다.',
  usage_examples = '[{"situation":"카톡으로 옛날 노래를 추천할 때","text":"이 노래 듣자마자 90년대 초 듀스 나를 돌아봐 느낌 났어"},{"situation":"SNS 댓글로 옛 댄스곡 감상을 남길 때","text":"90년대 초 세련됨의 정석, 나를 돌아봐"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'cdrxb4xa'
  and slug = '나를-돌아봐'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

