-- 나는 아직도 배가 고프다 (9ajbp6w6 / 나는-아직도-배가-고프다)
update public.memes set
  description = '2002년 한일 월드컵에서 한국 대표팀을 이끈 거스 히딩크 감독이 포르투갈전 이후 16강 진출을 확정했을 때 남긴 소감으로 전해지는 말이다. 목표를 이뤘는데도 만족하지 않겠다는 뜻을 담고 있다. 보도에 따라 옮긴 표현이 조금씩 달라서, ''아직도 배가 고프다''로 전한 기사와 ''승리에 굶주려 있다''로 전한 기사가 함께 남아 있다. 이후 온라인에서는 이 말을 빌려 쓴 패러디 게시물도 나왔다. 원래 말의 의미는 목표를 이룬 뒤에도 더 나아가겠다는 의지다.',
  origin = '2002년 한일 월드컵 조별리그 중 포르투갈전 이후 한국이 16강 진출을 확정했을 때의 소감이다. 경향신문은 이때 히딩크 감독이 ''나는 아직도 승리에 굶주려 있다''고 말했다고 전했고, 오센은 ''아직도 배가 고프다''라는 표현으로 옮겼다.',
  usage_note = '목표를 이룬 뒤에도 더 노력하겠다는 의지를 가볍게 표현할 때 인용한다. 원문 표현이 보도마다 달라 따옴표로 옮길 때는 출처를 함께 밝히는 것이 좋다.',
  caution = '이 말은 2002년 16강 진출 확정 무렵의 발언이므로 4강 이후의 말로 소개하면 틀린다. 정확한 원문도 보도마다 달라서 한 가지 문장으로 단정해 인용하지 않는 것이 안전하다.',
  usage_examples = '[{"situation":"카톡","text":"이번 목표 달성했지만 나는 아직도 배가 고프다"},{"situation":"SNS 댓글","text":"이 자세 완전 히딩크 어록급이다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '9ajbp6w6'
  and slug = '나는-아직도-배가-고프다'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

