-- B대면데이트 (rzggxnpk / B대면데이트)
update public.memes set
  description = '''B대면 데이트''는 유튜브 채널 ''피식대학''이 2021년 상반기에 선보인 소개팅 콩트 코너다. 가상의 부캐릭터들과 소개팅을 하는 설정이며, 최준(개그맨 김해준의 부캐)·방재호·차진석·이호창·임플란티드키드 등 다섯 캐릭터가 등장했다. 그중 카페 사장 최준은 쉼표 모양 앞머리와 느끼한 말투로 인기를 끌었고, 그 말투는 온라인에서 따라 쓰는 밈이 됐다. 코너는 약 7개월간 이어진 뒤 2021년 6월 캐릭터들이 작별 영상을 올리며 끝났다. 피식대학 콩트나 유튜브 부캐 캐릭터의 인기를 이야기할 때 대표 사례로 꺼내기 좋다.',
  origin = '유튜브 채널 ''피식대학''의 코너로, 개그맨 김해준이 연기한 부캐 최준이 대표 캐릭터다. 2021년 3월 2일 위키트리는 카페 사장 최준의 말투와 광고 활동을 다뤘고, 2021년 6월 12일 인사이트는 다섯 캐릭터가 작별 인사를 한 영상을 소개했다. 첫 방송 날짜는 확인된 출처가 없다.',
  usage_note = '소개팅 콩트나 유튜브 부캐 캐릭터 이야기를 할 때 피식대학의 대표 코너로 언급한다.',
  caution = '최준의 말투를 흉내 낼 때 실존 개그맨 김해준을 비하하는 것처럼 보이지 않도록 주의한다. 이 코너는 2021년 6월에 끝났으므로 지금도 방송 중인 것처럼 소개하지 않는다.',
  usage_examples = '[{"situation":"카톡 대화에서 웃긴 콩트를 추천할 때","text":"소개팅 콩트 웃긴 거 찾으면 B대면 데이트부터 봐봐"},{"situation":"SNS 댓글","text":"최준 쉼표 머리 말투 아직도 생각나네ㅋㅋ"}]'::jsonb,
  origin_year = 2021,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'rzggxnpk'
  and slug = 'B대면데이트'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

