-- 젝스키스 해체 (fu9du7qr / 젝스키스-해체)
update public.memes set
  description = '1997년 데뷔한 1세대 아이돌 젝스키스가 2000년 5월 18일 서울 기자회견에서 해체를 공식 발표한 사건이다. 이후 5월 20일 잠실 주경기장에서 열린 드림콘서트 무대가 팀의 마지막 공식 무대가 됐다. 같은 해 5월 31일에는 고별 앨범 《BLUE NOTE》가 나왔다. 해체 주도권을 두고는 멤버들의 발언이 엇갈린다. 은지원은 리더로서 먼저 해체를 꺼냈다고 2011년 방송에서 밝혔고, 이재진은 2005년 강제 해체였다고 말한 적이 있다. 해체 과정의 정확한 경위는 확인된 출처에서 더 찾기 어렵다.',
  origin = '1997년 데뷔한 그룹으로, 2000년 5월 18일 기자회견에서 해체를 발표했다. 조선일보 2016년 4월 28일 기사는 2000년 5월 20일 드림콘서트 공연을 마지막으로 공식 해체됐다고 전한다. 해체 발표 날짜는 위키백과 문서에 근거하며 원문 기사는 확인하지 못했다.',
  usage_note = '1세대 아이돌 시대나 2000년대 초 팬덤을 회상하며 당시 해체 소식을 떠올릴 때 쓴다.',
  caution = '해체를 누가 먼저 제안했는지는 멤버들의 발언이 엇갈리므로 단정하지 않는다. 해체 이후 재회 무대나 근황은 이 항목의 사실이 아니므로 섞어 쓰지 않는다.',
  usage_examples = '[{"situation":"카톡 대화에서 1세대 아이돌 얘기를 할 때","text":"1세대 아이돌 해체 얘기하면 젝스키스부터 떠오르더라"},{"situation":"SNS 댓글","text":"2000년 고별무대 얘기 나오니까 그때 생각 많이 난다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'fu9du7qr'
  and slug = '젝스키스-해체'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

