-- 나야 들기름 (4vcnfmsx / 나야-들기름)
update public.memes set
  description = '2024년 넷플릭스 요리 경연 ''흑백요리사'' 시즌1에서 최강록 셰프가 들기름을 쓴 조림 요리를 소개하며 ''나야~ 들기름''이라고 말한 장면에서 나온 말이다. 자신 있는 요리를 당당하게 내세우는 말투가 웃음을 주면서 밈이 됐다. 이후 들기름 막국수와 들깨 파스타 같은 음식 유행으로 이어졌고, 최강록 셰프가 마스터셰프 코리아 시즌2에서 남긴 ''이제 ~을 곁들인'' 말투와 겹쳐 쓰이기도 한다. 지금은 자신 있는 무엇인가를 소개하거나 추천할 때 가볍게 흉내 내는 말로 쓰인다.',
  origin = '2024년 넷플릭스 ''흑백요리사'' 시즌1에서 최강록 셰프가 들기름 조림을 내놓으며 한 말에서 시작됐다. 헤럴드경제는 이 말이 밈으로 화제가 되면서 들기름 막국수와 들깨 파스타가 주목받았다고 2025년 2월 보도했다.',
  usage_note = '자신 있는 음식이나 취향을 소개할 때 ''나야 ○○''처럼 장난스럽게 흉내 낸다. 원래 맥락이 들기름 요리이므로 다른 대상에 쓸 때는 농담임이 드러나게 쓰는 편이 자연스럽다.',
  caution = '원래 발언은 요리 소개 맥락이므로 실제 음식의 맛이나 평가와 연결해 과장하면 오해를 부른다. 발언의 정확한 문장이나 장면을 인용하려면 원 방송 자막을 따로 확인해야 한다.',
  usage_examples = '[{"situation":"동네 맛집 리뷰 댓글","text":"나야 들기름 막국수, 여기 인정"},{"situation":"카톡","text":"오늘 점심은 나야 들기름으로 가자 ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '4vcnfmsx'
  and slug = '나야-들기름'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

