-- 전사의 후예 (dfeqkrqb / 전사의-후예)
update public.memes set
  description = '1996년 9월 7일 데뷔한 H.O.T의 데뷔 앨범 『We Hate All Kinds of Violence』에 실린 첫 번째 싱글이다. 학교 폭력, 요즘 말로 하면 왕따 문제를 다룬 가사와 강렬한 퍼포먼스로 주목받았다. 이후 앨범의 두 번째 싱글 ''캔디''가 큰 인기를 끌면서 H.O.T가 1세대 아이돌을 대표하는 그룹으로 자리 잡는 데 힘이 실렸다. 지금은 1세대 아이돌 시절을 회고하거나 데뷔곡의 강렬함을 이야기할 때 인용된다. 곡명은 ''전사의 후예''이며 앨범 수록 표기에는 ''폭력시대''가 함께 붙어 있다.',
  origin = '1996년 9월 7일 SM엔터테인먼트를 통해 발매된 H.O.T 데뷔 앨범의 첫 번째 싱글이며, 앨범 3번 트랙에 ''전사의 후예 (폭력시대)''로 수록됐다. 학교 폭력을 비판하는 곡이라는 설명이 자료에 있다.',
  usage_note = '1세대 아이돌 문화를 회고할 때 H.O.T의 데뷔곡을 언급하거나, 강렬한 데뷔 무대를 떠올릴 때 쓴다.',
  caution = '''타이틀곡''이라는 표현은 열람한 자료에서 확인되지 않으므로 ''첫 번째 싱글''로 적어야 한다. 곡 주제가 학교 폭력이라 농담처럼 가볍게 쓰면 피해 경험이 있는 사람에게 상처가 될 수 있다.',
  usage_examples = '[{"situation":"카톡","text":"1세대 아이돌 얘기가 나오면 H.O.T 전사의 후예부터 떠오르지"},{"situation":"SNS 댓글","text":"90년대 데뷔곡 중에 이만큼 강렬한 곡 드물다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'dfeqkrqb'
  and slug = '전사의-후예'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

