-- PICK ME (국민 프로듀서) (g338yhcj / PICK-ME-(국민-프로듀서))
update public.memes set
  description = '2015년 12월 17일 디지털 싱글로 공개된 Mnet ''프로듀스101'' 시즌1의 주제곡이다. 같은 날 엠카운트다운에서 처음 무대가 공개됐고, 프로그램 연습생 98명이 함께 무대에 올랐다. 이 프로그램은 시청자가 ''국민 프로듀서''가 되어 데뷔 멤버와 콘셉트, 데뷔곡, 그룹명을 직접 정하는 구조였다. 곡은 EDM 기반의 댄스 곡으로, 프로그램을 소개하고 연습생을 알리는 역할을 맡았다. 지금은 투표로 선발되는 상황이나 경쟁 프로그램을 가볍게 흉내 낼 때 제목을 빌려 쓰며, 원곡을 가리킬 때는 ''프로듀스101 주제곡''이라고 함께 적는 편이 정확하다.',
  origin = '2015년 12월 17일 Mnet ''엠카운트다운''에서 첫 무대가 공개되고 같은 날 디지털 싱글로 발매됐다. 2016년 1월 방송을 앞두고 공개된 곡으로, 가온 디지털 차트 9위까지 올랐다고 영문 위키백과가 전한다.',
  usage_note = '투표나 선발 경쟁 상황을 유쾌하게 비유할 때, ''국민 프로듀서'' 콘셉트와 함께 제목을 인용한다.',
  caution = '''PICK ME''는 여러 곡과 프로그램에서 쓰이는 제목이므로 글에서는 ''프로듀스101 주제곡''이라고 덧붙여 원곡을 특정해야 한다. 영문 위키백과가 언급한 선거 캠페인 사용 설명은 출처 신뢰도가 낮다고 표시돼 있어 쓰지 않는다.',
  usage_examples = '[{"situation":"동창 단톡","text":"이번 총무 뽑기, 완전 PICK ME 분위기다"},{"situation":"SNS 댓글","text":"국민 프로듀서 여러분, 이번엔 제가 PICK ME!"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'g338yhcj'
  and slug = 'PICK-ME-(국민-프로듀서)'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

