-- 3!4! (c9msnu5q / 3!4!)
update public.memes set
  description = '1996년 6월 15일 발매된 룰라의 정규 4집 『올 시스템 고(All System Go)』의 타이틀곡이다. 작사·작곡·편곡은 모두 듀스 출신 이현도가 맡았다. 곡 도입부에 나오는 ''3! 4!'' 외침이 곡을 상징하는 장면으로 기억되며, 이 곡으로 룰라는 같은 해 SBS ''TV 가요 20''에서 3주 연속 1위를 차지해 다시 정상급 인기를 얻었다. 지금은 무언가를 시작하기 직전 흥을 돋우는 구호나 1990년대 댄스 가요를 회상할 때 가볍게 인용된다. 노래 제목보다 도입부의 구호 자체를 가리키는 경우도 있다. 구호의 표기는 ''3! 4!''다.',
  origin = '1996년 6월 15일 발매된 룰라 정규 4집 『올 시스템 고』의 타이틀곡이며, 작사·작곡·편곡은 듀스 출신 이현도가 맡았다. 국내 기사와 위키백과는 같은 해 SBS ''TV 가요 20''에서 3주 연속 1위를 기록했다고 전한다.',
  usage_note = '1990년대 댄스 가요를 회상하거나, 시작을 알리는 흥겨운 구호를 가볍게 흉내 낼 때 쓴다.',
  caution = '''3! 4!''는 노래 도입부의 외침이므로 일반 카운트다운과 같다고 단정하면 안 된다. 주차별 1위 기록은 방송 회차 자료로 확인된 범위만 인용하고, 확인되지 않은 세부 주차를 덧붙이지 않는다.',
  usage_examples = '[{"situation":"단톡방 출발 전","text":"자, 3! 4! 가보자"},{"situation":"SNS 댓글","text":"이 도입부 외침 들으니 룰라 3!4! 생각난다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'c9msnu5q'
  and slug = '3!4!'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

