-- 복불복 (km874pzj / 복불복)
update public.memes set
  description = '운이 좋고 나쁨을 뜻하는 한자어 ''복불복(福不福)''에서 온 말로, 복이 오거나 안 오거나 하는 운을 가리킨다. 예능에서는 벌칙자를 뽑거나 식사와 상품에서 누군가를 제외할 때 쓰는 랜덤 게임을 뜻하는 말로 굳어졌다. KBS 2TV ''1박 2일''에서 복불복 게임으로 벌칙을 정하는 방식이 자주 나오며 널리 알려졌고, MBC ''무한도전''도 비슷한 방식을 썼다는 설명이 있다. 지금은 게임뿐 아니라 결과가 운에 따라 갈리는 일상 상황에서도 가볍게 쓰인다. 사전적 뜻과 예능 용법을 함께 알아두면 헷갈리지 않는다.',
  origin = '사전적으로는 ''복이 오거나 안 오거나''라는 뜻이다. 한국어 위키백과는 KBS 2TV ''1박 2일''과 MBC ''무한도전''의 랜덤 벌칙 게임을 통해 예능 용어로 널리 쓰였다고 설명한다. ''1박 2일''은 2007년 8월 5일 정식 코너명으로 편성됐다고 적혀 있다.',
  usage_note = '운에 따라 벌칙이나 결과가 정해지는 상황을 가리킬 때 ''복불복이다''처럼 가볍게 쓴다.',
  caution = '운에 따라 결과가 갈리는 상황을 장난으로 쓰더라도 실제 불이익이 걸린 자리에서는 불만이 생길 수 있다. 예능 게임 방식은 방송마다 다르므로 특정 방송의 방식을 단정하지 말고 회차를 확인해서 쓴다.',
  usage_examples = '[{"situation":"팀 단톡","text":"오늘 점심 당번은 복불복으로 가자"},{"situation":"SNS 댓글","text":"내 운명은 그냥 복불복에 맡긴다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'km874pzj'
  and slug = '복불복'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

