-- To Heaven (45ynxkxh / To-Heaven)
update public.memes set
  description = 'To Heaven은 가수 조성모가 1998년 9월 발매한 첫 앨범 《To Heaven》의 이름이자, 그 노래를 드라마처럼 꾸민 뮤직비디오를 가리키는 말이다. 조성모는 방송 출연 없이 뮤직비디오로 먼저 알려진 ‘얼굴 없는 가수’로 활동했고, 뮤직비디오에 이병헌과 김하늘 등 배우들이 나와 영화 같은 구성이 화제가 됐다. 같은 해 10월 17일 방송에 처음 출연하기 전까지 얼굴을 드러내지 않은 마케팅 방식도 함께 기억된다. 지금은 90년대 말 발라드 뮤직비디오의 드라마타이즈 형식을 회고할 때 대표 사례로 인용된다. 뮤직비디오만 먼저 공개된 시기라 노래와 영상이 함께 기억되는 경우가 많다.',
  origin = '1998년 9월 3일 첫 앨범 《To Heaven》 발매 후 뮤직비디오만 공개되다가, 같은 해 10월 17일 방송에 처음 출연했다(위키백과 조성모 항목). 이병헌·김하늘의 뮤직비디오 출연은 오센 기사의 명단에서 확인했다.',
  usage_note = '90년대 말 발라드 뮤직비디오가 드라마처럼 만들어지던 흐름을 회고할 때 사례로 인용한다. 노래 자체의 평가보다 뮤직비디오 형식을 가리키는 맥락에서 쓴다.',
  caution = '뮤직비디오의 연출자와 촬영 시점은 확인하지 못했으므로 장면이나 줄거리를 단정하지 않는다. 배우 출연은 기사 명단에 나온 이병헌·김하늘 두 명만 인용하고, ‘국내 최초’ 같은 수식은 근거가 없어 쓰지 않는다.',
  usage_examples = '[{"situation":"카톡","text":"이 뮤비 완전 To Heaven 느낌이다, 영화 한 편 보는 줄"},{"situation":"SNS 댓글","text":"90년대 말 드라마 같은 뮤비 얘기 나오면 To Heaven부터 떠오르지"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '45ynxkxh'
  and slug = 'To-Heaven'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

