-- SK텔레콤 잘생겼다 (4my2fxb8 / SK텔레콤-잘생겼다)
update public.memes set
  description = 'SK텔레콤이 2014년 LTE-A 서비스를 알리며 내세운 광고 캠페인 ‘잘생겼다 엘티이 에이’를 가리키는 말이다. 이정재와 전지현이 모델로 나와 노래와 춤을 선보였고, 전지현은 직접 로고송을 부르기도 했다. 광고는 ‘잘생겼다’라는 말을 빌려 통신 기술을 소개하는 카피로 쓰였다. 방송 당시 ‘잘생겼다’ 시리즈와 ‘집나간 오빠’ CF가 소비자에게 호평을 받았다는 기사도 있었다. 같은 해 6월 광고 모델이 김연아로 바뀌면서 전지현이 출연한 ‘잘생겼다’ CF는 방송이 중단됐다. 이후 이 카피는 광고 카피를 이야기할 때 자주 꺼내는 사례로 남았다.',
  origin = '2014년 SK텔레콤 LTE-A 광고 캠페인. 3월 텐아시아 기사에서 이정재·전지현 출연과 노래·춤 구성을 확인했고, 6월 경향신문 기사에서 전지현 CF의 방송 중단과 김연아 모델 교체를 확인했다.',
  usage_note = '광고 카피를 떠올리며 기술이나 서비스가 좋다는 칭찬을 할 때 인용한다. 2010년대 중반 통신 광고 얘기를 할 때 함께 꺼내는 사례다.',
  caution = '카피의 말장난 해석은 열어본 기사에서 직접 설명하지 않았으므로 의미를 단정하지 않는다. 모델 교체를 두고 불화설이 돌았지만 회사는 부인했으니, 이를 사실처럼 옮기지 않는다.',
  usage_examples = '[{"situation":"카톡","text":"와이파이 속도 보니까 잘생겼다 소리가 절로 나오네ㅋㅋ"},{"situation":"SNS 댓글","text":"얼굴 말고 속도가 잘생겼다는 그 광고 카피 아직도 기억난다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '4my2fxb8'
  and slug = 'SK텔레콤-잘생겼다'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

