-- god의 육아일기 (7szbuhgt / god의-육아일기)
update public.memes set
  description = '2000년 1월 9일부터 2001년 5월 12일까지 MBC TV에서 방송된 관찰형 육아 예능 《god의 육아일기》를 가리키는 말이다. 그룹 god 멤버들이 비연예인 아기 한재민을 돌보며 낯가림하는 아기에게 다가가는 과정을 카메라가 따라갔다. 낯설어하는 아기를 달래기 위해 멤버들이 재롱잔치를 여는 장면처럼 육아의 일상이 담겼다. 국내 예능에서 관찰형 육아 프로그램의 출발점으로 소개되며, 아이돌이 실제 육아를 하는 과정을 그대로 따라간 형식이 특징이다. 이후 육아 예능을 이야기할 때 원조 사례로 자주 인용된다.',
  origin = '2000년 1월 9일부터 2001년 5월 12일까지 MBC TV에서 방송(위키백과 항목 기준). 출연 아기 한재민과 멤버들의 육아 장면은 위키백과와 방송 클립 제목에서 확인했다.',
  usage_note = '관찰 예능과 육아 예능의 원조를 이야기할 때 대표 사례로 인용한다. 아이돌이 육아를 하는 콘셉트를 설명할 때도 쓴다.',
  caution = '방송 기간과 출연진 정보는 위키백과 항목에 주로 기대고 있어 인용할 때 원문 확인이 필요하다. 시청률이나 그룹 인기에 미친 영향은 열어본 자료에서 확인하지 못했으므로 단정하지 않는다.',
  usage_examples = '[{"situation":"카톡","text":"요즘 육아 예능 보면 god의 육아일기가 원조긴 하지ㅋㅋ"},{"situation":"SNS 댓글","text":"관찰형 육아 예능 시작은 god의 육아일기 아닌가요"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '7szbuhgt'
  and slug = 'god의-육아일기'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

